static void fill_state(collector_t *c, uint64_t *state) {
    memset(state, 0, 32 * sizeof(*state));
    state[0] = c->b;
    state[1] = c->occupied;
    for (int r = 0; r < 4; r++) {
        state[2 + r] = c->R[r];
        state[6 + r] = c->S[r];
        state[10 + r] = c->acked[r];
        state[14 + r] = c->U[r];
    }
    state[18] = c->n_rx_data;
    state[19] = c->n_rx_ack;
    state[20] = c->n_tx_data;
    state[21] = c->n_tx_ack;
    state[22] = c->n_accepted;
    state[23] = c->n_dup;
    state[24] = c->n_blocked;
    state[25] = c->n_stale;
    state[26] = c->n_wire;
    state[27] = c->n_endpoint;
    state[28] = c->n_ack_ignored;
    state[29] = c->n_failed;
    state[30] = c->n_overwrite;
    state[31] = 0;
}
